SELECT CAST(COUNT(CASE WHEN p.gender = 'F' AND EXTRACT(YEAR FROM a.dischtime) BETWEEN 75 AND 85 AND a.dischtime - a.intime >= 7 AND (d.discharge_location = 'home' OR d.discharge_location = 'hospice' OR d.discharge_location = 'in-hospital death') THEN 1 END) AS FLOAT) / NULLIF(COUNT(DISTINCT a.subject_id), 0) AS proportion, PERCENTILE_CONT(0.7) WITHIN GROUP (ORDER BY (a.dischtime - a.intime)) AS percentile FROM admissions a JOIN patients p ON a.subject_id = p.subject_id JOIN transfers t ON a.subject_id = t.subject_id JOIN discharges d ON a.subject_id = d.subject_id WHERE p.anchor_age >= 80;